#!/usr/bin/env bash

# Guided setup for the Skemer release key.
#
# Creates an isolated keyring, a passphrase-protected full-secret backup, a
# revocation certificate, the signing subkey, and the public key material.
# The passphrase is entered by the operator and is not generated by the script.
# It writes a zip containing only the offline backup files (full secret and
# revocation certificate) so it can be stored separately from the passphrase.
#
# It never commits or pushes. It prints the exact git, tag, and Veldmuis-watch
# commands.

set -euo pipefail

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
skemer_repo="${SKEMER_REPO:-$(cd "${script_dir}/.." && pwd)}"
veldmuis_repo="${VELDMUIS_REPO:-${HOME}/Projects/veldmuis}"
keyhome="${SKEMER_KEYHOME:-${HOME}/.local/share/skemer/keyring-release}"
outdir="${SKEMER_KEY_OUTDIR:-${HOME}/skemer-release-key}"
uid="${SKEMER_KEY_UID:-Skemer release signing <skemer@veldmuislinux.org>}"
expire="${SKEMER_KEY_EXPIRE:-5y}"
environment="release"
passfile=""

cleanup() {
  if [[ -n "${passfile}" && -f "${passfile}" ]]; then
    rm -f -- "${passfile}"
  fi
  rm -rf -- "${outdir}/.verify-full" "${outdir}/.verify-ci" 2>/dev/null || true
}

trap cleanup EXIT

log() {
  printf '[skemer-key] %s\n' "$*"
}

die() {
  printf '[skemer-key] ERROR: %s\n' "$*" >&2
  exit 1
}

require_cmd() {
  command -v "$1" >/dev/null 2>&1 || die "Missing required command: $1"
}

expand_home() {
  # shellcheck disable=SC2088  # the leading ~/ is a literal match
  case "$1" in
    "~/"*) printf '%s/%s\n' "${HOME}" "${1#\~/}" ;;
    *) printf '%s\n' "$1" ;;
  esac
}

ask_yes() {
  local prompt="$1" answer=""
  read -r -p "${prompt} [Y/n] " answer
  [[ -z "${answer}" || "${answer}" =~ ^[Yy]([Ee][Ss])?$ ]]
}

ask_no() {
  local prompt="$1" answer=""
  read -r -p "${prompt} [y/N] " answer
  [[ "${answer}" =~ ^[Yy]([Ee][Ss])?$ ]]
}

gpgc() {
  GNUPGHOME="${keyhome}" gpg "$@"
}

usage() {
  cat <<'EOF'
Usage:
  setup-release-key.sh
  setup-release-key.sh --help

Environment overrides:
  SKEMER_REPO          Default: the repository containing this script
  VELDMUIS_REPO        Default: ~/Projects/veldmuis
  SKEMER_KEYHOME       Default: ~/.local/share/skemer/keyring-release
  SKEMER_KEY_OUTDIR    Default: ~/skemer-release-key
  SKEMER_KEY_UID       Default: Skemer release signing <skemer@veldmuislinux.org>
  SKEMER_KEY_EXPIRE    Default: 5y

The passphrase is entered interactively. The script creates:
  backup/skemer-release-full-secret.asc   full secret, offline
  backup/skemer-release-revoke.asc        revocation certificate, offline
  github/SKEMER_GPG_PRIVATE_KEY.asc       signing subkey, GitHub secret
  github/SKEMER_GPG_PASSPHRASE            passphrase, GitHub secret
  github/SKEMER_GPG_FPR                   fingerprint, GitHub secret
  public/skemer-release.gpg/.asc          public key material
  public/skemer-trusted                   public fingerprint
  skemer-release-backup-<date>.zip        zip of the two offline files

It never commits or pushes.
EOF
}

main() {
  case "${1:-}" in
    -h | --help)
      usage
      exit 0
      ;;
    "")
      ;;
    *)
      die "Unknown argument: $1"
      ;;
  esac

  [[ -t 0 ]] || die "Run this in a terminal; it needs an interactive passphrase."

  require_cmd gpg
  require_cmd gh
  require_cmd git
  require_cmd zip
  require_cmd awk
  require_cmd sed
  require_cmd install
  require_cmd mktemp

  gh auth status >/dev/null 2>&1 || die "Run gh auth login first."

  log "The Skemer release key is separate from the muis and Veldmuis keys."

  read -r -p "Veldmuis repository [${veldmuis_repo}]: " input
  [[ -z "${input}" ]] || veldmuis_repo="${input}"
  veldmuis_repo="$(expand_home "${veldmuis_repo}")"

  read -r -p "Output directory [${outdir}]: " input
  [[ -z "${input}" ]] || outdir="${input}"
  outdir="$(expand_home "${outdir}")"

  skemer_repo="$(expand_home "${skemer_repo}")"
  keyhome="$(expand_home "${keyhome}")"

  [[ -d "${skemer_repo}" ]] || die "Skemer repository not found: ${skemer_repo}"
  [[ -d "${veldmuis_repo}" ]] || die "Veldmuis repository not found: ${veldmuis_repo}"
  git -C "${skemer_repo}" rev-parse --is-inside-work-tree >/dev/null 2>&1 \
    || die "Not a git checkout: ${skemer_repo}"
  git -C "${veldmuis_repo}" rev-parse --is-inside-work-tree >/dev/null 2>&1 \
    || die "Not a git checkout: ${veldmuis_repo}"

  [[ -f "${skemer_repo}/.github/workflows/release.yml" ]] \
    || die "The release workflow is not in ${skemer_repo}; use the packaging PR branch or merge it first."
  [[ -f "${veldmuis_repo}/packages/veldmuis-skemer/PKGBUILD" ]] \
    || die "The veldmuis-skemer package is not in ${veldmuis_repo}; use the packaging PR branch or merge it first."

  case "${outdir}" in
    "${skemer_repo}"/* | "${veldmuis_repo}"/*)
      die "Do not put the output directory inside either repository: ${outdir}"
      ;;
  esac
  case "${keyhome}" in
    "${skemer_repo}"/* | "${veldmuis_repo}"/*)
      die "Do not put the keyring home inside either repository: ${keyhome}"
      ;;
  esac

  local remote_url repo_slug
  remote_url="$(git -C "${skemer_repo}" remote get-url origin 2>/dev/null || true)"
  repo_slug="$(printf '%s' "${remote_url}" \
    | sed -E 's#^git@github.com:##; s#^https://github.com/##; s#^ssh://git@github.com:##; s#\.git$##')"
  [[ "${repo_slug}" =~ ^[^/]+/[^/]+$ ]] \
    || die "Could not determine the GitHub repository from the origin remote in ${skemer_repo}."

  local skemer_branch veldmuis_branch
  skemer_branch="$(git -C "${skemer_repo}" branch --show-current)"
  veldmuis_branch="$(git -C "${veldmuis_repo}" branch --show-current)"

  log "Skemer checkout:  ${skemer_repo} (branch: ${skemer_branch:-detached})"
  log "Veldmuis checkout: ${veldmuis_repo} (branch: ${veldmuis_branch:-detached})"
  log "Keyring home:      ${keyhome}"
  log "Output directory:  ${outdir}"
  ask_yes "Use these paths?" || die "Aborted."

  if [[ "${skemer_branch}" == "main" || "${veldmuis_branch}" == "main" ]]; then
    log "WARNING: one checkout is on main. Create a branch before committing the public key files."
  fi

  install -d -m 700 "${keyhome}" "${outdir}"
  mkdir -p "${outdir}/backup" "${outdir}/github" "${outdir}/public"
  chmod 700 "${outdir}/backup" "${outdir}/github"

  local existing_fpr fpr=""
  existing_fpr="$(gpgc --list-secret-keys --with-colons "${uid}" 2>/dev/null \
    | awk -F: '$1 == "fpr" { print $10; exit }' || true)"

  if [[ -n "${existing_fpr}" ]]; then
    log "Found an existing Skemer release key:"
    gpgc --list-secret-keys --keyid-format=long "${existing_fpr}" || true
    ask_yes "Use this existing key?" \
      || die "Aborted; move or revoke the old key before creating another one."
    fpr="${existing_fpr}"
  else
    ask_yes "Generate a new Skemer release key for '${uid}' (${expire} expiry)?" \
      || die "Aborted."
  fi

  local pass1 pass2
  read -r -s -p "New Skemer release key passphrase (single line): " pass1
  echo
  read -r -s -p "Repeat the passphrase: " pass2
  echo
  [[ -n "${pass1}" ]] || die "The passphrase cannot be empty."
  [[ "${pass1}" == "${pass2}" ]] || die "The passphrases do not match."
  unset pass2

  passfile="$(mktemp)"
  chmod 600 "${passfile}"
  printf '%s' "${pass1}" > "${passfile}"
  unset pass1

  if [[ -z "${fpr}" ]]; then
    log "Generating the primary key..."
    gpgc --batch --pinentry-mode loopback --passphrase-file "${passfile}" \
      --quick-generate-key "${uid}" ed25519 cert "${expire}"
    fpr="$(gpgc --list-keys --with-colons "${uid}" \
      | awk -F: '$1 == "fpr" { print $10; exit }')"
    [[ -n "${fpr}" ]] || die "Could not read the new key fingerprint."
    log "Adding the sign-only subkey..."
    gpgc --batch --pinentry-mode loopback --passphrase-file "${passfile}" \
      --quick-add-key "${fpr}" ed25519 sign "${expire}"
  fi

  log "Key fingerprint: ${fpr}"

  log "Exporting the offline backup..."
  gpgc --batch --pinentry-mode loopback --passphrase-file "${passfile}" \
    --armor --export-secret-keys "${fpr}" \
    > "${outdir}/backup/skemer-release-full-secret.asc"

  [[ -r "${keyhome}/openpgp-revocs.d/${fpr}.rev" ]] \
    || die "Revocation certificate not found at ${keyhome}/openpgp-revocs.d/${fpr}.rev"
  cp "${keyhome}/openpgp-revocs.d/${fpr}.rev" \
    "${outdir}/backup/skemer-release-revoke.asc"

  log "Exporting the GitHub signing subkey..."
  gpgc --batch --pinentry-mode loopback --passphrase-file "${passfile}" \
    --armor --export-secret-subkeys "${fpr}" \
    > "${outdir}/github/SKEMER_GPG_PRIVATE_KEY.asc"
  printf '%s\n' "${fpr}" > "${outdir}/github/SKEMER_GPG_FPR"
  cp "${passfile}" "${outdir}/github/SKEMER_GPG_PASSPHRASE"

  gpgc --batch --export "${fpr}" > "${outdir}/public/skemer-release.gpg"
  gpgc --batch --armor --export "${fpr}" > "${outdir}/public/skemer-release.asc"
  printf '%s\n' "${fpr}" > "${outdir}/public/skemer-trusted"

  chmod 600 \
    "${outdir}/backup/skemer-release-full-secret.asc" \
    "${outdir}/backup/skemer-release-revoke.asc" \
    "${outdir}/github/SKEMER_GPG_PRIVATE_KEY.asc" \
    "${outdir}/github/SKEMER_GPG_PASSPHRASE"
  chmod 644 \
    "${outdir}/github/SKEMER_GPG_FPR" \
    "${outdir}/public/skemer-release.gpg" \
    "${outdir}/public/skemer-release.asc" \
    "${outdir}/public/skemer-trusted"

  log "Verifying the full-secret backup imports..."
  install -d -m 700 "${outdir}/.verify-full/home"
  GNUPGHOME="${outdir}/.verify-full/home" gpg --batch --import \
    "${outdir}/backup/skemer-release-full-secret.asc" >/dev/null 2>&1 \
    || die "The full-secret backup did not import."
  local sec_count ssb_count
  sec_count="$(GNUPGHOME="${outdir}/.verify-full/home" gpg --with-colons --list-secret-keys 2>/dev/null \
    | awk -F: '$1 == "sec" { count++ } END { print count + 0 }')"
  ssb_count="$(GNUPGHOME="${outdir}/.verify-full/home" gpg --with-colons --list-secret-keys 2>/dev/null \
    | awk -F: '$1 == "ssb" { count++ } END { print count + 0 }')"
  [[ "${sec_count}" -ge 1 && "${ssb_count}" -ge 1 ]] \
    || die "The full-secret backup is incomplete (no primary or signing subkey)."

  log "Verifying the GitHub subkey signs with the passphrase..."
  install -d -m 700 "${outdir}/.verify-ci/home"
  GNUPGHOME="${outdir}/.verify-ci/home" gpg --batch --import \
    "${outdir}/github/SKEMER_GPG_PRIVATE_KEY.asc" >/dev/null 2>&1 \
    || die "The signing-subkey export did not import."
  printf 'verify\n' > "${outdir}/.verify-ci/input"
  GNUPGHOME="${outdir}/.verify-ci/home" gpg --batch --pinentry-mode loopback \
    --passphrase-file "${passfile}" --local-user "${fpr}" \
    --detach-sign "${outdir}/.verify-ci/input" 2>/dev/null \
    || die "The signing subkey did not sign with the passphrase."
  GNUPGHOME="${outdir}/.verify-ci/home" gpg --batch --verify \
    "${outdir}/.verify-ci/input.sig" "${outdir}/.verify-ci/input" >/dev/null 2>&1 \
    || die "The signing-subkey test signature did not verify."

  gpgconf --homedir "${outdir}/.verify-full/home" --kill gpg-agent >/dev/null 2>&1 || true
  gpgconf --homedir "${outdir}/.verify-ci/home" --kill gpg-agent >/dev/null 2>&1 || true
  rm -rf "${outdir}/.verify-full" "${outdir}/.verify-ci"

  log "Copying the public key material into the checkouts..."
  local skemer_keys="${skemer_repo}/packaging/keys"
  local veldmuis_keys="${veldmuis_repo}/development/skemer-keyring"
  mkdir -p "${skemer_keys}" "${veldmuis_keys}"

  if [[ -r "${skemer_keys}/skemer-trusted" ]]; then
    local old_fpr
    old_fpr="$(tr -d '[:space:]' < "${skemer_keys}/skemer-trusted" | tr '[:lower:]' '[:upper:]')"
    if [[ "${old_fpr}" != "${fpr}" ]]; then
      ask_yes "Replace the existing public key (${old_fpr}) with ${fpr}?" \
        || die "Aborted."
    fi
  fi

  cp "${outdir}/public/skemer-release.gpg" "${skemer_keys}/skemer-release.gpg"
  cp "${outdir}/public/skemer-release.asc" "${skemer_keys}/skemer-release.asc"
  cp "${outdir}/public/skemer-trusted" "${skemer_keys}/skemer-trusted"
  cp "${outdir}/public/skemer-release.gpg" "${veldmuis_keys}/skemer-release.gpg"
  cp "${outdir}/public/skemer-trusted" "${veldmuis_keys}/skemer-trusted"
  chmod 644 "${skemer_keys}"/* "${veldmuis_keys}"/*

  cat > "${outdir}/README.txt" <<EOF
Skemer release key
Fingerprint: ${fpr}
Created: $(date -u +%Y-%m-%dT%H:%M:%SZ)

backup/skemer-release-full-secret.asc
  FULL SECRET KEY (primary + signing subkey). Passphrase-protected.
  Store offline. Never commit.

backup/skemer-release-revoke.asc
  REVOCATION CERTIFICATE. Store offline. Do not publish unless revoking.

github/SKEMER_GPG_PRIVATE_KEY.asc
  SIGNING SUBKEY. Set as GitHub secret SKEMER_GPG_PRIVATE_KEY.

github/SKEMER_GPG_PASSPHRASE
  PASSPHRASE. Set as GitHub secret SKEMER_GPG_PASSPHRASE.
  Store it separately in your vault.

github/SKEMER_GPG_FPR
  FINGERPRINT. Set as GitHub secret SKEMER_GPG_FPR. Public.

public/skemer-release.gpg
public/skemer-release.asc
public/skemer-trusted
  PUBLIC KEY MATERIAL. Commit to the Skemer and Veldmuis repositories.
EOF
  chmod 644 "${outdir}/README.txt"

  local backup_zip
  backup_zip="${outdir}/skemer-release-backup-$(date +%Y-%m-%d-%H%M%S).zip"
  cp "${outdir}/README.txt" "${outdir}/backup/README.txt"
  chmod 644 "${outdir}/backup/README.txt"
  (
    cd "${outdir}/backup"
    zip -q "${backup_zip}" \
      skemer-release-full-secret.asc \
      skemer-release-revoke.asc \
      README.txt
  )
  chmod 600 "${backup_zip}"
  log "Offline backup zip: ${backup_zip}"

  if ask_yes "Set the GitHub release environment secrets now?"; then
    if ! gh api "repos/${repo_slug}/environments/${environment}" >/dev/null 2>&1; then
      log "Creating the release environment..."
      gh api --method PUT "repos/${repo_slug}/environments/${environment}" >/dev/null \
        || die "Could not create the release environment; create it in repository settings."
    fi
    gh secret set SKEMER_GPG_PRIVATE_KEY --env "${environment}" --repo "${repo_slug}" \
      < "${outdir}/github/SKEMER_GPG_PRIVATE_KEY.asc"
    gh secret set SKEMER_GPG_FPR --env "${environment}" --repo "${repo_slug}" \
      --body "${fpr}"
    gh secret set SKEMER_GPG_PASSPHRASE --env "${environment}" --repo "${repo_slug}" \
      < "${outdir}/github/SKEMER_GPG_PASSPHRASE"
    log "GitHub secrets set:"
    gh secret list --env "${environment}" --repo "${repo_slug}"
  else
    log "Skipped GitHub secrets. Set them manually:"
    log "  gh secret set SKEMER_GPG_PRIVATE_KEY --env ${environment} --repo ${repo_slug} < ${outdir}/github/SKEMER_GPG_PRIVATE_KEY.asc"
    log "  gh secret set SKEMER_GPG_FPR --env ${environment} --repo ${repo_slug} --body ${fpr}"
    log "  gh secret set SKEMER_GPG_PASSPHRASE --env ${environment} --repo ${repo_slug} < ${outdir}/github/SKEMER_GPG_PASSPHRASE"
  fi

  log "Store the zip and the passphrase separately."
  log "After setting the GitHub secrets, delete ${outdir}/github."
  log "Public files are in:"
  log "  ${skemer_keys}/skemer-release.gpg"
  log "  ${skemer_keys}/skemer-release.asc"
  log "  ${skemer_keys}/skemer-trusted"
  log "  ${veldmuis_keys}/skemer-release.gpg"
  log "  ${veldmuis_keys}/skemer-trusted"
  log "Review and commit them yourself:"
  printf '  git -C %q add packaging/keys/skemer-release.gpg packaging/keys/skemer-release.asc packaging/keys/skemer-trusted\n' "${skemer_repo}"
  printf '  git -C %q commit -m "chore: add the Skemer release public key"\n' "${skemer_repo}"
  printf '  git -C %q push\n' "${skemer_repo}"
  printf '  git -C %q add development/skemer-keyring/skemer-release.gpg development/skemer-keyring/skemer-trusted\n' "${veldmuis_repo}"
  printf '  git -C %q commit -m "chore(skemer): vendor the Skemer release public key"\n' "${veldmuis_repo}"
  printf '  git -C %q push\n' "${veldmuis_repo}"
  log "After merging both PRs, tag the first release from the main Skemer checkout:"
  log "  git -C ${HOME}/Projects/Skemer switch main"
  log "  git -C ${HOME}/Projects/Skemer pull --ff-only"
  log "  git -C ${HOME}/Projects/Skemer tag -a v0.1.0 -m 'Skemer 0.1.0'"
  log "  git -C ${HOME}/Projects/Skemer push origin v0.1.0"
  log "Then run the Veldmuis release watch:"
  log "  gh workflow run skemer-release-watch.yml --repo bornmanr/veldmuis"
}

main "$@"
